mapper.select:
SELECT a.id, a.user_id, u.username, a.name, a.description, a.avatar, a.system_prompt, a.welcome_message, a.knowledge_base_id, a.tool_ids, a.is_public, a.sort_order, a.deleted, a.create_time, a.update_time, stats.public_count, stats.private_count FROM agent a LEFT JOIN sys_user u ON a.user_id = u.id CROSS JOIN ( SELECT SUM(CASE WHEN is_public = 1 THEN 1 ELSE 0 END) AS public_count, SUM(CASE WHEN is_public = 0 THEN 1 ELSE 0 END) AS private_count FROM agent WHERE deleted = 0
AND user_id = #{userId}
AND (user_id = #{userId} OR is_public = 1)
AND (name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
) stats WHERE a.deleted = 0
AND a.user_id = #{userId}
AND (a.user_id = #{userId} OR a.is_public = 1)
AND (a.name LIKE CONCAT('%', #{keyword}, '%') OR a.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.sort_order ASC, a.create_time DESC
